import { Component, computed, inject } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { ActivatedRoute, Router } from '@angular/router';
import { catchError, EMPTY, map, Observable, switchMap } from 'rxjs';
import { CinemaApi } from '../cinema-api';
import { showDate } from '../dates';
import { Movie, Screening } from '../models';
import { buildAuditorium, Cell } from '../seat-map/auditorium';

export type SeatState = 'available' | 'selected' | 'unavailable' | 'accessible';

interface LoadedScreening {
  screening: Screening;
  movie: Movie;
}

@Component({
  selector: 'app-seat-selection',
  templateUrl: './seat-selection.html',
  styleUrl: './seat-selection.scss',
})
export class SeatSelectionComponent {
  private readonly api = inject(CinemaApi);
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);

  protected readonly data = toSignal(
    this.route.paramMap.pipe(switchMap((params) => this.load(Number(params.get('id'))))),
  );

  protected readonly rows = computed(() => {
    const screening = this.data()?.screening;
    return screening ? buildAuditorium(new Set(screening.occupiedSeats)) : [];
  });

  protected showDate(screening: Screening): string {
    return showDate(screening.date, screening.time);
  }

  protected stateOf(cell: Cell): SeatState {
    if (cell.occupied) {
      return 'unavailable';
    }
    return cell.kind === 'seat' && cell.accessible ? 'accessible' : 'available';
  }

  private load(id: number): Observable<LoadedScreening> {
    return this.api.screening(id).pipe(
      switchMap((screening) =>
        this.api.movie(screening.movieId).pipe(map((movie) => ({ screening, movie }))),
      ),
      catchError(() => {
        this.router.navigateByUrl('/');
        return EMPTY;
      }),
    );
  }
}

