$gap: 4px;
$label: 28px;
$aisle: 72px;
$side-block: 4 * $seat + 3 * $gap;
$centre-block: 16 * $seat + 15 * $gap;
$couch: 2 * $seat + $gap;

:host {
  display: block;
  padding: 24px;
  text-align: center;
}

.subtitle {
  margin: 4px 0 0;
}

.auditorium {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: fit-content;
  margin: 0 auto;
}

.limit {
  margin: 16px 0;
}

.screen {
  width: 100%;
  padding: 6px 0;
  border-radius: 4px;
  background: var(--mat-sys-surface-container-highest);
  font-size: 12px;
