1	import { Component, computed, inject, signal } from '@angular/core';
2	import { toSignal } from '@angular/core/rxjs-interop';
3	import { MatButtonModule } from '@angular/material/button';
4	import { ActivatedRoute, Router } from '@angular/router';
5	import { catchError, EMPTY, switchMap, tap } from 'rxjs';
6	import { BookingService } from '../booking';
7	import { CinemaApi } from '../cinema-api';
8	import { showDate } from '../dates';
9	import { Screening } from '../models';
10	import { buildAuditorium, Cell, seatsIn } from '../seat-map/auditorium';
11	import { ToastService } from '../toast/toast';
12	
13	export type SeatState = 'available' | 'selected' | 'unavailable' | 'accessible';
14	
15	const MAX_SEATS = 10;
16	
17	interface RowLine {
18	  row: number;
19	  text: string;
20	}
21	
22	@Component({
23	  selector: 'app-seat-selection',
24	  imports: [MatButtonModule],
25	  templateUrl: './seat-selection.html',
26	  styleUrl: './seat-selection.scss',
27	})
28	export class SeatSelectionComponent {
29	  private readonly api = inject(CinemaApi);
30	  private readonly bookings = inject(BookingService);
31	  private readonly router = inject(Router);
32	  private readonly route = inject(ActivatedRoute);
33	  private readonly toast = inject(ToastService);
34	
35	  private readonly selectedKeys = signal<ReadonlySet<string>>(new Set());
36	
37	  protected readonly data = toSignal(
38	    this.route.paramMap.pipe(
39	      switchMap((params) =>
40	        this.api.screeningWithMovie(Number(params.get('id'))).pipe(
41	          tap(({ screening }) => this.openBooking(screening.id)),
42	          catchError(() => {
43	            this.router.navigateByUrl('/');
44	            return EMPTY;
45	          }),
46	        ),
47	      ),
48	    ),
49	  );
50	
51	  protected readonly rows = computed(() => {
52	    const screening = this.data()?.screening;
53	    return screening ? buildAuditorium(new Set(screening.occupiedSeats)) : [];
54	  });
55	
56	  private readonly selectedCells = computed(() => {
57	    const keys = this.selectedKeys();
58	    return this.rows()
59	      .flatMap((row) => row.segments)
60	      .flatMap((segment) => (segment.kind === 'block' ? segment.cells : []))
61	      .filter((cell) => keys.has(cell.key));
62	  });
63	
64	  protected readonly seatCount = computed(() =>
65	    this.selectedCells().reduce((total, cell) => total + seatsIn(cell), 0),
66	  );
67	
68	  protected readonly rowLines = computed<RowLine[]>(() => {
69	    const labelsByRow = new Map<number, string[]>();
70	    for (const cell of this.selectedCells()) {
71	      const label = cell.kind === 'seat' ? `${cell.column}` : `${cell.start}-${cell.end}`;
72	      labelsByRow.set(cell.row, [...(labelsByRow.get(cell.row) ?? []), label]);
73	    }
74	    return [...labelsByRow].map(([row, labels]) => ({ row, text: labels.join(', ') }));
75	  });
76	
77	  protected subtitle(screening: Screening): string {
78	    return showDate(screening.date, screening.time);
79	  }
80	
81	  protected stateOf(cell: Cell): SeatState {
82	    if (cell.occupied) {
83	      return 'unavailable';
84	    }
85	    if (this.selectedKeys().has(cell.key)) {
86	      return 'selected';
87	    }
88	    return cell.kind === 'seat' && cell.accessible ? 'accessible' : 'available';
89	  }
90	
91	  protected toggle(cell: Cell): void {
92	    if (cell.occupied) {
93	      return;
94	    }
95	    const keys = new Set(this.selectedKeys());
96	    if (keys.has(cell.key)) {
97	      keys.delete(cell.key);
98	    } else if (this.seatCount() + seatsIn(cell) > MAX_SEATS) {
99	      this.toast.show(`Maximum ${MAX_SEATS} seats per booking`);
100	      return;
101	    } else {
